    /// Scope: read. Since: 1.4.0.
    pub fn chart_elements_get(&self, args: DataChartElementsGetArgs) -> Result<Value, Error> {
        self.c.call("chart_elements_get", args.into_value())
    }

    /// Writes a workbench's bars of one market and interval, up to its cursor and never past it, as CSV into the export folder set on Settings > Agents, under this agent's name; answers the file's path, uri, rows and bytes, never the rows. For a span too long to read in pages.
