    pub fn export_bars(&self, args: DataExportBarsArgs) -> Result<Value, Error> {
        self.c.call("export_bars", args.into_value())
    }

    /// Writes one market's ticks of one day that have happened at the workbench's cursor, never one past it, as CSV into the export folder under this agent's name; answers the file's path, uri, rows and bytes. Only a day the replay holds in memory is written.
    /// Scope: read. Since: 1.0.0.
    pub fn export_ticks(&self, args: DataExportTicksArgs) -> Result<Value, Error> {
        self.c.call("export_ticks", args.into_value())
    }

    /// Writes a workbench's closed candles of one market up to its cursor - never past it, never the one still forming - with triple-barrier labels (the Python SDK's bentrix.data.triple_barrier) as CSV into the export folder under this agent's name: a position entered at the next candle's open (a long at its ask, a short at its bid), a target and a stop in points, a horizon in candles; label 1 the target met first, -1 the stop, 0 neither, and ambiguous where one candle touched both (the stop's). Answers the file's path, uri, rows and bytes.
    /// Scope: read. Since: 1.14.0.
