    pub fn set_style(&self, args: StudySetStyleArgs) -> Result<Value, Error> {
        self.c.call("study_set_style", args.into_value())
    }

    /// Sets on which intervals a study is drawn, as the Visibility tab does. Patch field: visibility. Answers the chart.
