    pub fn set_visibility(&self, args: StudySetVisibilityArgs) -> Result<Value, Error> {
        self.c.call("study_set_visibility", args.into_value())
    }

    /// Forgets a custom study a program defined. Refused while any chart holds a study of it, and for a script's: a script's study is the person's file. Answers the kind.
